#define _GNU_SOURCE
#include <malloc.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
static void snapshot(const char *phase,int cycle,size_t live) {
    unsigned long pages=0,resident=0;
    FILE *input=fopen("/proc/self/statm","r");
    if(!input||fscanf(input,"%lu %lu",&pages,&resident)!=2) exit(3);
    fclose(input);
    struct mallinfo2 info=mallinfo2();
    printf("{\"phase\":\"%s\",\"cycle\":%d,\"live_bytes\":%zu,\"rss_bytes\":%lu,\"vms_bytes\":%lu,\"uordblks\":%zu,\"fordblks\":%zu,\"arena\":%zu,\"hblkhd\":%zu}\n",
        phase,cycle,live,resident*(unsigned long)sysconf(_SC_PAGESIZE),pages*(unsigned long)sysconf(_SC_PAGESIZE),
        info.uordblks,info.fordblks,info.arena,info.hblkhd);
}
int main(void) {
    setvbuf(stdout,NULL,_IONBF,0);
    /* Only this short-lived process; force arena allocations and controlled retention. */
    if(!mallopt(M_MMAP_THRESHOLD,128*1024*1024)||!mallopt(M_TRIM_THRESHOLD,-1)) return 2;
    snapshot("baseline",-1,0);
    void *blocks[64];const size_t size=512*1024;
    for(int cycle=0;cycle<3;cycle++) {
        for(int n=0;n<64;n++) { blocks[n]=malloc(size);if(!blocks[n])return 4;memset(blocks[n],n+1,size); }
        snapshot("allocated",cycle,64*size);
        for(int n=0;n<64;n++)free(blocks[n]);
        snapshot("freed",cycle,0);
        malloc_trim(0);
        snapshot("trimmed",cycle,0);
    }
    for(int n=0;n<32;n++) { blocks[n]=malloc(size);if(!blocks[n])return 5;memset(blocks[n],n+1,size); }
    snapshot("live-held",3,32*size);
    malloc_trim(0);snapshot("live-after-trim",3,32*size);
    for(int n=0;n<32;n++)free(blocks[n]);
    return 0;
}
